const a = $json.body;
const lvl = a.rule?.level || 0;

// Wazuh level → IRIS severity_id (2=Unspec,3=Info,4=Low,5=High,6=Critical)
let sev = 2;
if (lvl >= 13) sev = 6;
else if (lvl >= 10) sev = 5;
else if (lvl >= 7) sev = 4;
else if (lvl >= 5) sev = 3;

const normalized = {
  rule: {
    id: a.rule?.id,
    level: lvl,
    description: a.rule?.description,
    mitre: a.rule?.mitre?.id || [],
    groups: a.rule?.groups || []
  },
  agent: a.agent || {},
  timestamp: a.timestamp,
  data: a.data || {},
  full_log: a.full_log || "",
  iris_severity_id: sev
};

const claudeBody = {
  model: "claude-sonnet-4-6",
  max_tokens: 1500,
  temperature: 0,
  system: "You are an L1 SOC analyst triaging a Wazuh SIEM alert from an isolated homelab. Determine a verdict (true_positive, benign, or needs_review), map to MITRE ATT&CK IDs, extract every IOC present in the alert, write concise analyst notes (3-6 sentences), and recommend one action. Respond with ONLY a valid JSON object, no prose or markdown fences. Only reference IOCs literally present; never invent values. If evidence is insufficient use needs_review. recommended_action must be one of: none, monitor, block_ip, disable_account, isolate_host, escalate_to_analyst (advisory only; a human approves all actions). Schema: {verdict, severity, confidence, mitre, iocs, analysis, recommended_action, case_title}.",
  messages: [ { role: "user", content: JSON.stringify(normalized) } ]
};

return [{ json: { normalized, claudeBodyString: JSON.stringify(claudeBody) } }];

// Claude's triage output (JSON string in content[0].text)
let triage = {};
try {
  const raw = $json.content?.[0]?.text || "{}";
  triage = JSON.parse(raw.replace(/```json|```/g, "").trim());
} catch (e) {
  triage = { verdict: "needs_review", severity: "medium", confidence: 0,
             mitre: [], iocs: [], analysis: "TRIAGE PARSE FAILURE: " + ($json.content?.[0]?.text || "").slice(0,300),
             recommended_action: "escalate_to_analyst", case_title: "Unparseable triage output" };
}

// Pull the normalized alert from the earlier node
const n = $('Normalize & Map Severity').item.json.normalized;

// Build IRIS alert body
const irisBody = {
  alert_title: triage.case_title || (n.rule.description + " on " + (n.agent.name || "unknown")),
  alert_description: triage.analysis || "No analysis provided",
  alert_source: "wazuh-casefile",
  alert_severity_id: n.iris_severity_id,
  alert_status_id: 2,
  alert_customer_id: 1,
  alert_note: "Verdict: " + triage.verdict + " | Confidence: " + triage.confidence +
              " | MITRE: " + (triage.mitre || []).join(", ") +
              " | Recommended: " + triage.recommended_action,
  alert_tags: (triage.mitre || []).join(",")
};

return [{ json: { triage, irisBody, iris_severity_id: n.iris_severity_id } }];
